import Ajv from 'ajv';
import {jest} from '@jest/globals';
import {ToolRegistry} from './registry.js';

describe('ToolRegistry', () => {
  it('rejects a wrong-typed property with its field and expected type without leaking its value', async () => {
    const registry = new ToolRegistry();
    let executorCalls = 0;
    registry.register(
      {
        name: 'ssn_lookup',
        description: 'Look up a record by identifier',
        inputSchema: {
          type: 'object',
          properties: {ssn: {type: 'string'}},
        },
      },
      async () => {
        executorCalls += 1;
        return 'sunny';
      }
    );

    const response = await registry.execute('ssn_lookup', {ssn: 123456789});

    expect({executorCalls, result: response.result}).toEqual({
      executorCalls: 0,
      result: expect.stringMatching(/ssn.*string/i),
    });
    expect(response.result).not.toContain('123456789');
  });

  it('passes valid input with undeclared properties through unchanged', async () => {
    const registry = new ToolRegistry();
    const input = {location: 'Paris', requestId: 'req-123'};
    const executorInputs: Array<Record<string, unknown>> = [];
    registry.register(
      {
        name: 'weather',
        description: 'Get weather',
        inputSchema: {
          type: 'object',
          properties: {location: {type: 'string'}},
          required: ['location'],
        },
      },
      async receivedInput => {
        executorInputs.push(receivedInput);
        return 'sunny';
      }
    );

    await registry.execute('weather', input);

    expect(executorInputs).toEqual([input]);
  });

  it('compiles a function-valued schema once per schema object across repeated executions', async () => {
    const compile = jest.spyOn(Ajv.prototype, 'compile');
    const registry = new ToolRegistry();
    const schema = {type: 'object', properties: {location: {type: 'string'}}};
    registry.register(
      () => ({name: 'weather', description: 'Get weather', inputSchema: schema}),
      async () => 'sunny'
    );

    await Promise.all(Array.from({length: 10}, () => registry.execute('weather', {location: 'Paris'})));

    expect(compile).toHaveBeenCalledTimes(1);
    compile.mockRestore();
  });
});

--- spec ---
# Tool Input Validation

| Field  | Value                |
| ------ | -------------------- |
| Issue  | re-cinq/HALEngine#37 |
| Status | In Progress          |

Every tool registered in `src/orchestration/tools/registry.ts` declares a JSON Schema `inputSchema` that is forwarded to the configured AI provider, and `ToolRegistry.execute` validates the model-supplied `input` against that schema before calling the tool's executor. When validation fails, `execute` returns a rejection `ToolResponse` describing what was wrong rather than throwing, so the orchestrator feeds the failure back to the model as a `tool_result` within the existing tool-round budget.

## Validation at execute time

- When `input` omits a property listed in `required`, `ToolRegistry.execute` returns a `ToolResponse` whose `result` names the missing property as required and never invokes the executor ([validated by: rejects input missing a required property with a ToolResponse and never calls the executor](../../src/orchestration/tools/registry.acceptance.test.ts#L16)).
- When `input` supplies a property whose value does not match its declared JSON Schema type, `ToolRegistry.execute` returns a `ToolResponse` naming the failing field path and expected type without invoking the executor, and neither `result` nor the emitted log record contains the offending property value ([validated by: rejects a wrong-typed property naming the field and expected type without leaking the offending value to the result or logs](../../src/orchestration/tools/registry.acceptance.test.ts#L46), [validated by: rejects a wrong-typed property with its field and expected type without leaking its value](../../src/orchestration/tools/registry.test.ts#L6)).
- When `input` satisfies `required`, declared property types and `enum`, `ToolRegistry.execute` invokes the executor once and passes the input object through unchanged — including undeclared extra properties — without injecting `additionalProperties: false`, coercing types or applying defaults ([validated by: passes valid input with undeclared properties through unchanged](../../src/orchestration/tools/registry.test.ts#L33)).
- When `ToolRegistry.execute` is called with a tool name that has not been registered, it throws `Unknown tool: <name>` because an unregistered tool is a programming or configuration error rather than a recoverable input mistake.

## Schema compilation and caching

- A static `ToolDefinition` has its `inputSchema` compiled once at `register` time, so a schema that is not valid JSON Schema throws synchronously from `register` with an error message naming the offending tool ([validated by: throws at register time naming the tool when a static inputSchema cannot be compiled](../../src/orchestration/tools/registry.acceptance.test.ts#L94)).
- A static tool's `inputSchema` is compiled at `register` time and reused on every `execute` call without re-reading or re-compiling `definition.inputSchema`.
- A function-valued `ToolDefinitionSource` resolves its definition on each `execute` call and validates against the `inputSchema` returned for that call, caching compiled validators by schema object reference (`WeakMap`) so distinct returned schemas each enforce their own rules ([validated by: compiles a function-valued schema once per schema object across repeated executions](../../src/orchestration/tools/registry.test.ts#L32)).

## Orchestrator tool-loop recovery

- Because a schema rejection returns a `ToolResponse` instead of throwing, `src/orchestration/chatOrchestrator.ts` sends the rejection `result` back to the provider as a `tool_result` message, allowing the model to issue a corrected tool call on the next round and complete the turn within `maxToolRounds` ([validated by: returns a schema rejection as a tool_result in the orchestrator loop so the model can correct the call on the next round](../../src/orchestration/tools/registry.acceptance.test.ts#L112)).

